"""Build ten static report routes and the homepage from one editable fixture file."""
from pathlib import Path
from bs4 import BeautifulSoup
from datetime import date
from html import escape as e
import json,re
BASE=Path(__file__).resolve().parent;D=BASE/'dist'; data=json.loads((D/'cars.json').read_text());cars=data['cars']
def soup(t):return BeautifulSoup(t,'html.parser')
def datefmt(t):return date.fromisoformat(t).strftime('%-d %b %Y')
def km(n):return f'{n:,}'
def money(n):
 t=str(round(n));tail=t[-3:];head=t[:-3];groups=[]
 while head:groups.insert(0,head[-2:]);head=head[:-2]
 return '₹'+(','.join(groups)+',' if groups else '')+tail
def rows(items):return '<div class="record-rows">'+''.join(f'<div><span>{a}</span><b>{b}</b></div>' for a,b in items)+'</div>'
def visual(title,body,status=''):
 return f'<div class="feature-visual"><div class="visual-heading">{title}'+(f'<span class="status amber">{status}</span>' if status else '')+f'</div>{body}</div>'
def source(label):return f'<div class="source-line">{label} · record set dated 24 Nov 2026</div>'
def nextstep(title,question,copy,guide=None):return f'<aside class="report-next-step"><span>What to ask next</span><h3>{title}</h3><p class="seller-question">“{question}”</p><p>{copy}</p>'+ (f'<a class="text-link" href="guide-{guide}.html">Read the {guide} guide</a>' if guide else '')+'</aside>'
def sethtml(el,html):el.clear();el.append(soup(html))
def chapter(id,num,label,title,copy,body):return soup(f'<section class="report-section" id="{id}"><div class="chapter-intro"><p class="eyebrow"><span class="chapter-number" aria-hidden="true">{num}</span>{label}</p><h2>{title}</h2><p>{copy}</p></div><div class="report-section-body">{body}</div></section>').section
options=''.join(f'<option value="sample-{c["id"]}.html">{c["year"]} {e(c["name"])} · {e(c["variant"])}</option>' for c in cars)
for c in cars:
 s=soup((BASE/'data/report-template-original.html').read_text());s.title.string=f'VIB — {c["year"]} {c["name"]} report';
 s.head.append(soup('<link href="vehicles.css" rel="stylesheet"><script src="vehicles.js" defer></script>'))
 sethtml(s.select_one('.sample-banner'),'<p>Vehicle history report · 24 Nov 2026</p><button class="print-button" type="button">Print report</button>')
 selector=soup(f'<form class="vehicle-picker"><label for="report-vehicle">Explore another car</label><select id="report-vehicle" name="vehicle">{options}</select><button type="submit">Open report</button></form>');selector.select_one(f'option[value="sample-{c["id"]}.html"]')['selected']='';s.select_one('.sample-top').insert_after(selector)
 top=s.select_one('.sample-top');sethtml(top,f'<div><div class="mini-identity"><span class="mini-brand">VIB <small>Vehicle history report</small></span></div><p class="sample-label">Vehicle record</p><h1>{e(c["name"])}</h1><p class="variant-name">{e(c["variant"])}</p><p class="mini-sub">{c["year"]} · {e(c["fuel"])} · {e(c["transmission"])} · {c["registration"]}</p><p>24 Nov 2026 · {c["reportId"]}</p></div><div class="identity-photo"><a href="#photos"><img src="{c["photos"][0]["src"]}" alt="{e(c["name"])} — {e(c["photos"][0]["view"])}" width="640" height="420"></a><p>Reference vehicle photograph · {len(c["photos"])} photos in this file</p></div>')
 sethtml(s.select_one('.coverage-preview'),f'<h2>{c["headline"]}</h2><p>{len(c["services"])} service records · {c["owners"]} owner'+('s' if c['owners']>1 else '')+f' · {km(c["declaredKm"])} km declared. Read the dated evidence, then check the car and original documents.</p><a href="#coverage-gaps">See record coverage</a>')
 delta=c['services'][-1]['km']-c['declaredKm'];mismatch=delta>0;last=c['services'][-1]
 findings=[('mileage','Verify readings' if mismatch else 'Read the history','Mileage records conflict' if mismatch else ('Service history has a gap' if c['serviceGap'] else 'Mileage increases across the records'),f'{km(delta)} km below the last service reading. Ask for the original documents.' if mismatch else ('Ask for the missing service invoices before deciding.' if c['serviceGap'] else f'{len(c["services"])} dated service entries are available.')),
 ('finance','Documents needed' if c['lenderActive'] else 'Check at transfer','Lender entry remains active' if c['lenderActive'] else 'No lender entry in the record','A closure letter is available; check the registration update.' if c['closureDocument'] else ('Ask for closure documents before transfer.' if c['lenderActive'] else 'Confirm the current registration details before transfer.')),
 ('claims' if c['claim'] else 'challans','Review repair' if c['claim'] else 'Check documents','A repair claim is recorded' if c['claim'] else ('Unpaid challans recorded' if c['challans'] else 'Review the document dates'),f'{money(c["claim"]["amount"])} settled. Review the invoice and inspect the repair.' if c['claim'] else (f'{money(sum(x["amount"] for x in c["challans"]))} recorded as unpaid.' if c['challans'] else 'Policy, registration and PUC dates are listed below.'))]
 sethtml(s.select_one('.summary-grid'),''.join(f'<a href="#{a}"><span class="status amber">{b}</span><h3>{h}</h3><p>{p}</p></a>' for a,b,h,p in findings))
 # Real photographs stay distinct from invented historical evidence.
 photos=''.join(f'<button class="photo-open" type="button" data-photo="{p["src"]}" data-caption="{e(c["name"])} · {e(p["view"])}" aria-label="Enlarge {e(p["view"])} photo"><img src="{p["src"]}" alt="{e(c["name"])} — {e(p["view"])}" loading="lazy" width="600" height="400"><span>{e(p["view"])}</span></button>' for p in c['photos'])
 photo=chapter('photos','01','Vehicle photos','Put a face to the file.','Start with the exterior and cabin. Photos help you spot what to ask about when you see the car.',f'<div class="vehicle-gallery">{photos}</div><p class="photo-provenance">CARS24 listing photographs, retrieved 24 Nov 2026. Capture dates are unavailable. These reference photos are not evidence of the repair history below.</p>')
 score=c['score']
 score_html=f'<div class="report-score"><div class="score-number"><strong>{score["value"]}</strong><span>/100</span></div><div><h2>{score["label"]}</h2><p>Review the evidence and inspect the car.</p><small>Sample condition score · preset for this report preview</small></div></div>'
 s.select_one('.sample-summary').insert_before(soup(score_html))
