 # Mileage chart, chart controls and service work share a single source array.
 rr=[dict(x,source='Service invoice') for x in c['services']]+[{'date':c['sellerDate'],'km':c['declaredKm'],'source':'Seller declaration'}];mx=max(x['km'] for x in rr)*1.15
 pts=[(42+i*468/(len(rr)-1),185-x['km']/mx*150) for i,x in enumerate(rr)];line=' '.join(('M' if i==0 else 'L')+f'{x:.1f} {y:.1f}' for i,(x,y) in enumerate(pts[:-1]));sx,sy=pts[-2];dx,dy=pts[-1]
 chart=f'<div class="chart fixture-chart"><svg role="img" aria-label="Mileage readings from {km(rr[0]["km"])} to {km(rr[-1]["km"])} kilometres; '+('a lower later reading needs verification' if mismatch else 'readings increase over time')+f'" viewBox="0 0 540 220"><path d="M36 35H520 M36 85H520 M36 135H520 M36 185H520" stroke="#d3dde4" fill="none"/><path class="record-line" d="{line}" fill="none"/><path class="declaration-line" d="M{sx} {sy}L{dx} {dy}" fill="none"/>'+''.join(f'<circle cx="{x}" cy="{y}" r="5" fill="#426784"/>' for x,y in pts)+f'<text x="36" y="212">{datefmt(rr[0]["date"])}</text><text x="410" y="212">Nov 2026</text></svg><p class="chart-instruction">Choose a dated reading to see its source.</p><div class="chart-controls">'+''.join(f'<button type="button" aria-pressed="{str(i==len(rr)-1).lower()}" data-value="{datefmt(r["date"])} · {r["source"]} · {km(r["km"])} km">{datefmt(r["date"])}</button>' for i,r in enumerate(rr))+f'</div><p class="chart-readout" aria-live="polite">{datefmt(rr[-1]["date"])} · Seller declaration · {km(rr[-1]["km"])} km</p></div>'
 comp=f'<div class="reading-comparison"><div><span>Last service record</span><strong>{km(last["km"])} <small>km</small></strong><time>{datefmt(last["date"])}</time></div><div><span>Later seller declaration</span><strong>{km(c["declaredKm"])} <small>km</small></strong><time>20 Nov 2026</time></div></div><p class="reading-difference">'+(f'<strong>{km(delta)} km</strong> lower than the last service reading. The cause needs verification.' if mismatch else 'No decrease in the available readings. Missing records can still leave gaps.')+'</p>'
 table='<div class="table-scroll"><table><caption>Service visits and work recorded</caption><thead><tr><th>Date / reading</th><th>Work / source</th><th>Invoice</th></tr></thead><tbody>'+''.join(f'<tr><td>{datefmt(r["date"])}<br>{km(r["km"])} km</td><td>{r["work"]}<small class="cell-source">{e(r["workshop"])} · {r["id"]}</small></td><td>{money(r["amount"])}</td></tr>' for r in c['services'])+'</tbody></table></div>'
 sethtml(s.select_one('#mileage .report-section-body'),visual('Mileage history',comp+chart,'Verify readings' if mismatch else 'Dated records')+table+nextstep('Compare the original readings','Can we check the service invoices against the odometer?','Read the dates, vehicle details and seller’s explanation together. A discrepancy alone does not establish tampering.','mileage')+source('Service invoices and seller declaration'))
 identity=rows([('Vehicle',e(c['name'])+' '+e(c['variant'])),('Year / body style',f'{c["year"]} / {c["bodyType"]}'),('Fuel / transmission',f'{c["fuel"]} / {c["transmission"]}'),('Registration region',c['region']),('Masked registration',c['registration']),('First registration',datefmt(c['registeredOn'])),('Owner number',str(c['owners'])),('Usage',c['usage']),('Modifications',c['modifications']),('Registration valid until',datefmt(c['validUntil']))])
 ownership='<h3>Ownership trail</h3>'+rows([('First registered',datefmt(c['registeredOn'])),*([('Second owner recorded','12 Feb 2025')] if c['owners']==2 else []),('Factory equipment / engine details','Not verified in this record set')])
 sethtml(s.select_one('#ownership .report-section-body'),visual('Identity and specifications',identity)+ownership+nextstep('Match the car to the documents','Do these details match your registration certificate?','Compare the fuel, transmission, vehicle identifiers and ownership details with the car. Confirm equipment in person.')+source('Registration record'))
 finance=rows([('Lender entry','Active' if c['lenderActive'] else 'No entry recorded'),('Closure document','Available · dated 14 Oct 2026' if c['closureDocument'] else 'Not provided'),('Loan balance / repayment status','Unavailable'),('Next step','Check registration update' if c['closureDocument'] else ('Request lender closure documents' if c['lenderActive'] else 'Verify the latest registration record'))])
 sethtml(s.select_one('#finance h2'),'An active entry deserves a closer look.' if c['lenderActive'] else 'Check the entry before the transfer.')
 sethtml(s.select_one('#finance .report-section-body'),visual('Finance and transfer',finance)+nextstep('Check the transfer documents','Can we review the lender documents before transfer?','An active entry does not show the loan balance or establish missed payments. Verify the current entry and any closure documents.','finance')+source('Registration finance entry'))
 claim=c['claim'];body=rows([('Claim date',datefmt(claim['date'])),('Repair description',claim['part']),('Amount / status',money(claim['amount'])+' / Settled'),('Accident severity','Not established')]) if claim else '<p>No claim entry is included in the available records. This does not establish an accident-free history.</p>'
 body+= '<h3>Condition records</h3>'+rows([('Structural damage / total loss','Not assessed'),('Flood / airbag deployment','Not assessed'),('Engine / transmission repairs','No supporting record available')])
 policy=rows([('Cover type',c['policyType']),('Policy period','8 Jul 2026–'+datefmt(c['policyUntil'])),('Status on report date','Within recorded policy period')])
 sethtml(s.select_one('#claims .report-section-body'),visual('Claim and repair history',body,'Claim recorded' if claim else 'No claim entry')+visual('Insurance policy',policy)+nextstep('Understand any repair','Can we review the repair invoices and inspect the work?','A claim amount does not establish accident severity. Exterior reference photos are not linked to historical repair events.','inspection')+source('Policy and claim record set'))
 total=sum(x['amount'] for x in c['challans']);ch=rows([(f'{x["offence"]} · {x["id"]}',f'{money(x["amount"])} · {x["status"]} · {datefmt(x["date"])}') for x in c['challans']]+[('Unpaid total',money(total))]) if total else '<p>No unpaid challan entry is included in the available records. Check the current status before transfer.</p>'
 validity=rows([('Registration valid until',datefmt(c['validUntil'])),('PUC valid until',datefmt(c['pucUntil'])),('PUC on report date','Expired · renewal needed' if c['pucUntil']<'2026-11-24' else 'Within recorded validity'),('Road tax','Paid in the record'),('Theft / court / FIR','Coverage unavailable'),('Recalls','Coverage unavailable')])
 sethtml(s.select_one('#challans .report-section-body'),visual('Challans',ch,'Unpaid entries' if total else 'Check current status')+visual('Documents and legal coverage',validity)+nextstep('Check the current status','Can we verify payments and document validity together?','Use current source records and the original documents before transfer. Unavailable legal searches do not give an all-clear result.')+source('Challan and registration record set'))
 low,high=c['priceRangeLakh'];price=f'<div class="value-range">₹{low:.1f}–{high:.1f} lakh</div><p>{e(c["name"])} · {c["year"]} · Gurugram</p><p>A reference range for this sample. It is not a live valuation or an offer.</p>'
 listings='<h3>Previous asking prices</h3>'+rows([(datefmt(x['date']),money(x['amount'])) for x in c['askingPrices']])+'<p class="photo-provenance">Asking prices are not completed-sale prices. Comparable sales and peer ranking are unavailable.</p>'
 sethtml(s.select_one('#valuation .chapter-intro > p:last-child'),'Read a reference range alongside previous asking prices. An estimate starts a conversation; it is not an offer.')
 sethtml(s.select_one('#valuation .report-section-body'),visual('Price context',price)+listings+nextstep('Discuss what supports the price','How does the asking price reflect the records and today’s condition?','Read the service history, repair documents and inspection together before discussing price.')+source('Reference range and listing history'))
 events=[(c['registeredOn'],'First registration',f'{c["region"]} · ownership begins')]+[(r['date'],'Service visit',f'{km(r["km"])} km · {r["work"]}') for r in c['services']]+([(claim['date'],'Repair claim settled',f'{money(claim["amount"])} · {claim["part"]}')] if claim else [])+[(r['date'],'Asking price recorded',money(r['amount'])) for r in c['askingPrices']]+[(c['sellerDate'],'Seller mileage declaration',km(c['declaredKm'])+' km')]+([('2025-02-12','Ownership transfer','Second owner recorded')] if c['owners']==2 else [])
 timeline='<ol class="event-timeline">'+''.join(f'<li><time datetime="{d}">{datefmt(d)}</time><div><h3>{h}</h3><p>{p}</p></div></li>' for d,h,p in sorted(events,key=lambda x:x[0]))+'</ol>'
 s.select_one('#coverage-gaps').insert_before(chapter('timeline','08','The complete timeline','Read the dates together.','Registration, service, repair and sale records in one sequence. Gaps remain visible.',timeline))
 nav=[('photos','Photos'),('mileage','Mileage & service'),('ownership','Identity & ownership'),('finance','Finance & transfer'),('claims','Insurance & repairs'),('challans','Challans & documents'),('valuation','Market context'),('timeline','Timeline')]
 for el in [s.select_one('.report-nav'),s.select_one('.report-jump nav')]:sethtml(el,''.join(f'<a href="#{id}">{label}</a>' for id,label in nav))
 sethtml(s.select_one('.report-jump summary'),'Report sections<span>8 sections</span>')
